using System.ComponentModel.DataAnnotations;
namespace SimplexLawFirm.Models;
public enum DiscoveryBundleStatus { Draft, PendingPrivilegeReview, ReadyForExchange, Exchanged, OpposingBundleReceived, Compliant, GapsIdentified, EscalatedFormalRequest, Closed, AwaitingPrivilegeReview = PendingPrivilegeReview, Received = OpposingBundleReceived }
public enum PrivilegeDecision { NotFlagged, Pending, WithholdApproved, OverruledDisclose, ApprovedWithheld = WithholdApproved }
public sealed class DiscoveryBundle { public int Id {get;set;} public int CaseId {get;set;} public Case Case {get;set;}=null!; public int AttorneyId {get;set;} public ApplicationUser Attorney {get;set;}=null!; public DiscoveryBundleStatus Status {get;set;}=DiscoveryBundleStatus.Draft; [MaxLength(320)] public string OpposingAttorneyEmail {get;set;}=""; [MaxLength(200)] public string OpposingAttorneyName {get;set;}=""; [MaxLength(80)] public string ExchangeToken {get;set;}=""; public DateTime? ExchangeExpiresAtUtc {get;set;} public DateTime? ExchangedAtUtc {get;set;} public DateTime? AccessedAtUtc {get;set;} public DateTime? OpposingBundleReceivedAtUtc {get;set;} [MaxLength(4000)] public string? ComplianceNotes {get;set;} public ICollection<DiscoveryBundleItem> Items {get;set;}=[]; public ICollection<OpposingDisclosureDocument> OpposingDocuments {get;set;}=[]; }
public sealed class DiscoveryBundleItem { public int Id {get;set;} public int DiscoveryBundleId {get;set;} public DiscoveryBundle DiscoveryBundle {get;set;}=null!; public int DocumentId {get;set;} public Document Document {get;set;}=null!; public bool ProposedPrivileged {get;set;} [MaxLength(2000)] public string? PrivilegeReason {get;set;} public PrivilegeDecision PrivilegeDecision {get;set;} public int? DirectorId {get;set;} [MaxLength(2000)] public string? DirectorReason {get;set;} public DateTime? DecidedAtUtc {get;set;} }
public sealed class OpposingDisclosureDocument { public int Id {get;set;} public int DiscoveryBundleId {get;set;} public DiscoveryBundle DiscoveryBundle {get;set;}=null!; [MaxLength(260)] public string FileName {get;set;}=""; [MaxLength(500)] public string RelativePath {get;set;}=""; [MaxLength(120)] public string ContentType {get;set;}="application/octet-stream"; public long SizeBytes {get;set;} public DateTime UploadedAtUtc {get;set;}=DateTime.UtcNow; }
